MC.registerPack({"id":"msm","cards":[{"id":"05001a","name":"미즈 마블","en":"* Ms. Marvel","type":"hero","enc":false,"unique":true,"hp":10,"atk":1,"thw":1,"def":1,"hs":5,"tr":["CHAMPION","INHUMAN"],"traits":["챔피언","인휴먼"],"text":"\"형태발생\" — <b>반응</b>: 당신이 [[공격]], [[저지]], [[방어]] 이벤트를 플레이한 후, 미즈 마블을 소진 → 그 이벤트를 당신의 손으로 되돌립니다."},{"id":"05001b","name":"카말라 칸","en":"* Kamala Khan","type":"alter","enc":false,"unique":true,"hp":10,"rec":5,"hs":6,"tr":["INHUMAN"],"traits":["인휴먼"],"text":"10대 정신 — <b>행동</b>: 당신의 덱에서 미즈 마블 카드가 버려질 때까지 카드를 버립니다. 그러고 나서 그 카드를 당신의 손에 더합니다(라운드마다 1회 제한.)"},{"id":"05002","name":"레드 대거","en":"* Red Dagger","type":"ally","enc":false,"unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":3,"res":"Y","cls":"Hero","tr":["CHAMPION"],"traits":["챔피언"],"text":"<b>난입</b>: 레드 대거가 격파될 때, 서로 다른 유형의 자원을 2개 소모 → 적 하나에게 피해 2점을 입히고 레드 대거를 당신의 손으로 되돌림."},{"id":"05003","name":"거대한 손","en":"Big Hands","type":"event","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero","tr":["ATTACK","SUPERPOWER"],"traits":["공격","슈퍼파워"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 4점을 입힙니다."},{"id":"05004","name":"몰래 지나가기","en":"Sneak By","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["SKILL","THWART"],"traits":["기술","저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 음모 하나에서 위협을 3만큼 제거합니다."},{"id":"05005","name":"위글 룸","en":"Wiggle Room","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Hero","tr":["DEFENSE","SUPERPOWER"],"traits":["방어","슈퍼파워"],"text":"<b>히어로 난입</b><i>(방어)</i>: 당신이 피해를 받으려 할 때, 그 피해에서 3점을 방지합니다. 카드 1장을 뽑습니다."},{"id":"05006","name":"아미르 칸","en":"* Aamir Khan","type":"support","enc":false,"unique":true,"cost":1,"res":"B","cls":"Hero","tr":["PERSONA"],"traits":["페르소나"],"text":"<b>일상 행동</b>: 아미르 칸을 소진 → 당신의 버린 더미에서 카드 1장을 당신의 덱 맨 아래로 옮겨놓음. 그러고 나서 카드 1장을 뽑음."},{"id":"05007","name":"브루노 카렐리","en":"* Bruno Carrelli","type":"support","enc":false,"unique":true,"cost":1,"res":"R","cls":"Hero","tr":["PERSONA"],"traits":["페르소나"],"text":"<b>일상 행동</b>: 브루노 카렐리를 소진 → 당신의 손에서 카드 1장을 이 카드에 뒷면으로 장착.\n<b>행동</b>: 브루노 카렐리를 소진 → 이 카드에 장착된 카드를 3장까지 당신의 손에 더함."},{"id":"05008","name":"나키아 바하디르","en":"* Nakia Bahadir","type":"support","enc":false,"unique":true,"cost":1,"res":"Y","cls":"Hero","tr":["PERSONA"],"traits":["페르소나"],"text":"<b>일상 행동</b>: 나키아 바하디르를 소진 → 당신이 이번 페이즈에 플레이하는 다음 카드의 자원 비용을 1만큼 감소시킴."},{"id":"05009","name":"생물동역학 중합체 슈트","en":"* Biokinetic Polymer Suit","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"B","cls":"Hero","tr":["ARMOR"],"traits":["갑옷"],"text":"<b>히어로 자원</b>: 생물동역학 중합체 슈트를 소진 → 이벤트를 플레이할 때만 소모할 수 있는 [wild] 자원을 생성. "},{"id":"05010","name":"거대화!","en":"Embiggen!","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["CONDITION","SUPERPOWER"],"traits":["상태","슈퍼파워"],"text":"<b>히어로 난입</b>: 당신이 [[공격]] 이벤트를 플레이할 때, 거대화!를 소진 → 그 이벤트가 입히는 피해를 2점 증가시킵니다."},{"id":"05011","name":"축소","en":"Shrink","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["CONDITION","SUPERPOWER"],"traits":["상태","슈퍼파워"],"text":"<b>히어로 난입</b>: 당신이 [[저지]] 이벤트를 플레이할 때, 축소!를 소진 → 그 이벤트가 제거하는 위협을 2만큼 증가시킵니다."},{"id":"05012","name":"노바","en":"* Nova","type":"ally","enc":false,"sub":"샘 알렉산더","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":4,"res":"Y","cls":"Protection","tr":["CHAMPION"],"traits":["챔피언"],"text":"<b>난입</b>: 적이 당신에게 공격을 개시할 때, [energy] 자원을 소모 → 그 적에게 피해 2점을 입힘."},{"id":"05013","name":"뒤로 물러서세요!","en":"Get Behind Me!","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Protection","tr":[],"traits":[],"text":"<b>히어로 난입</b>: 조우 덱에서 배반 카드가 공개될 때, 그 카드의 \"<b>공개될 때</b>\" 효과를 모두 무효화합니다. 대신 빌런이 당신을 공격합니다.","link":"01078"},{"id":"05014","name":"선제공격","en":"Preemptive Strike","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Protection","tr":["DEFENSE"],"traits":["방어"],"text":"<b>히어로 난입</b><i>(방어)</i>: 빌런이 공격하는 동안 강화 카드가 뒤집힐 때, 뒤집힌 강화 카드에 있는 모든 강화 아이콘([boost])을 무효화합니다. 그러고 나서 이렇게 무효화한 강화 아이콘마다 빌런에게 피해 1점을 입힙니다."},{"id":"05015","name":"태클","en":"Tackle","type":"event","enc":false,"unique":false,"cost":3,"res":"R","cls":"Protection","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나를 기절시킵니다. 이 카드에 [physical] 자원을 지불했다면, 그 적에게 피해 3점을 입힙니다."},{"id":"05016","name":"수호의 힘","en":"The Power of Protection","type":"resource","enc":false,"unique":false,"res":"G","cls":"Protection","tr":[],"maxDeck":2,"traits":[],"text":"덱마다 최대 2장.\n수호<i>(녹색)</i> 카드에 이 카드를 비용으로 지불하는 한, 이 카드가 생성하는 자원은 2배가 됩니다.","link":"01079"},{"id":"05017","name":"에너지 방벽","en":"Energy Barrier","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Protection","tr":["ITEM","TECH"],"uses":{"n":3,"kind":"reflection"},"traits":["도구","과학"],"text":"사용 (반사 카운터 3). <b>난입:</b> 당신이 피해를 받으려 할 때, 이 카드에서 반사 카운터를 1만큼 제거 → 그 피해에서 1점을 방지하고 적 하나에게 피해 1점을 입힘."},{"id":"05018","name":"록조","en":"* Lockjaw","type":"ally","enc":false,"unique":true,"hp":4,"atk":2,"atkStar":true,"atkCons":2,"thw":2,"thwStar":true,"thwCons":2,"cost":4,"res":"R","cls":"Basic","tr":["INHUMAN"],"traits":["인휴먼"],"text":"당신은 당신의 차례 동안 록조를 당신의 버린 더미에서 플레이해도 됩니다(자원 비용은 지불합니다)."},{"id":"05019","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"05020","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"05021","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"05022","name":"어벤져스 맨션","en":"Avengers Mansion","type":"support","enc":false,"unique":false,"cost":4,"res":"B","cls":"Basic","tr":["AVENGER","LOCATION"],"maxPer":1,"traits":["어벤저","장소"],"text":"플레이어마다 최대 1장.\n<b>행동</b>: 어벤져스 맨션을 소진 → 플레이어 하나를 선택해 카드 1장을 뽑게 함.","link":"01091"},{"id":"05023","name":"인내","en":"Endurance","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Basic","tr":["CONDITION"],"maxPer":1,"traits":["상태"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n당신은 생명력 +3을 받습니다."},{"id":"05024","name":"향상된 반사신경","en":"Enhanced Reflexes","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Basic","tr":["CONDITION"],"uses":{"n":3,"kind":"energy"},"traits":["상태"],"text":" 사용 (에너지 카운터 3).\n<b>히어로 자원</b>: 향상된 반사신경을 소진하고 이 카드에서 에너지 카운터 1개 제거 → [energy] 자원을 생성."},{"id":"05025","name":"동이 트면 집으로","en":"Home by Dawn","type":"obligation","enc":true,"set":"Ms. Marvel","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>카말라 칸 플레이어에게 이 카드를 줍니다.</i></b>\n당신은 일상 형태로 카드를 뒤집어도 됩니다. 다음 중 하나를 선택합니다.\n• 카말라 칸을 소진 → 동이 트면 집으로를 게임에서 제거.\n• 당신이 조종하는 [[페르소나]] 지원 1장을 버립니다. 이렇게 버려진 지원이 없다면, 이 카드는 쇄도를 얻습니다. 이 의무 카드를 버립니다."},{"id":"05026","name":"왜요? 세대","en":"Generation Why?","type":"side","enc":true,"set":"Ms. Marvel Nemesis","unique":false,"boost":3,"start":2,"startStar":true,"hazard":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어의 덱 맨 위에서 플레이 영역에 있는 동료마다, 그리고 [[페르소나]] 지원마다 카드를 버립니다."},{"id":"05027","name":"토머스 에디슨","en":"* Thomas Edison","type":"minion","enc":true,"set":"Ms. Marvel Nemesis","unique":true,"hp":3,"atk":1,"sch":3,"boost":2,"tr":["BIRD","GENIUS"],"nemesis":true,"traits":["조류","천재"],"text":"당신이 다른 하수인과 교전 중인 동안, 토머스 에디슨은 피해를 입을 수 없습니다.\n<i>(미즈 마블의 숙적 하수인).</i>"},{"id":"05028","name":"에디슨의 거대한 로봇","en":"* Edison's Giant Robot","type":"minion","enc":true,"set":"Ms. Marvel Nemesis","unique":true,"hp":8,"atk":2,"sch":1,"boost":1,"tr":["ROBOT"],"traits":["로봇"],"text":"에디슨의 거대한 로봇은 피해를 입을 수 없습니다.\n<b>히어로 행동:</b> [mental] 자원을 소모 → 페이즈의 끝까지, 이 카드의 인쇄된 글 상자를 백지화한 것으로 봅니다."},{"id":"05029","name":"수확","en":"Harvest","type":"treachery","enc":true,"set":"Ms. Marvel Nemesis","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이 영역에 있는 모든 [[페르소나]] 지원을 소진합니다. 이렇게 소진된 지원마다, 빌런이 입은 피해 1점을 회복합니다. 이렇게 소진된 [[페르소나]] 지원이 없다면, 이 카드는 쇄도를 얻습니다."},{"id":"05030","name":"근접 공격","en":"Melee","type":"event","enc":false,"unique":false,"cost":3,"res":"B","cls":"Aggression","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 3점을 입힙니다. 다른 적 하나에게 피해 3점을 입힙니다."},{"id":"05031","name":"뇌진탕 일격","en":"Concussive Blow","type":"event","enc":false,"unique":false,"cost":3,"res":"R","cls":"Justice","tr":["ATTACK"],"maxPer":1,"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나를 혼란에 빠뜨립니다. 이 카드에 [physical] 자원을 지불했다면, 그 적에게 피해 3점을 입힙니다."},{"id":"05032","name":"사기 증진","en":"Morale Boost","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Leadership","tr":[],"traits":[],"text":"<b>히어로 행동</b>: 히어로 하나를 선택합니다. 라운드의 끝까지, 그 히어로는 저지 +1, 공격 +1, 방어 +1을 받습니다."},{"id":"05033","name":"휴식 시간","en":"Down Time","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"R","cls":"Basic","tr":["CONDITION"],"maxPer":1,"traits":["상태"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n당신의 일상은 회복 +2를 받습니다."}]});
